sys_script.script:
(function executeRule(current, previous /*null when async*/) {

     try {
        var questionId = current.x_631631_sc_grc_0_question.toString();
        var value = current.x_631631_sc_grc_0_value.toString();
        var stringValue = current.x_631631_sc_grc_0_string_value.toString();
        var action = current.x_631631_sc_grc_0_action.toString();

        gs.info('Processing external attestation for question: ' + questionId);
        gs.info('  Value: ' + value);
        gs.info('  String Value: ' + stringValue);
        gs.info('  Action: ' + action);

        // Get the question record
        var question = new GlideRecord('asmt_assessment_instance_question');
        // question.setWorkflow(false); // Bypass workflows and run with elevated privileges!

        if (question.get(questionId)) {
            // Update the appropriate field
            if (stringValue) {
                question.string_value = stringValue;  // Direct assignment
                gs.info('Set string_value to: ' + stringValue);
            } else if (value) {
                question.value = value;  // Direct assignment for choice fields
                gs.info('Set value to: ' + value);
            }

            question.update();
            gs.info('Question updated successfully, sys_mod_count: ' + question.sys_mod_count);

            // Update parent assessment instance state to "in_progress" when action is 'save'
			var instanceId;
			var instance;
            if (action === 'save') {
                instanceId = question.instance.toString();
                gs.info('Updating assessment instance state to in_progress: ' + instanceId);

                instance = new GlideRecord('asmt_assessment_instance');
                instance.setWorkflow(false); // Bypass workflows

                if (instance.get(instanceId)) {
                    // Only update if current state is 'ready' to avoid overwriting completed assessments
                    if (instance.state == 'ready' || instance.state =='wip') {
                        instance.state = 'wip';
                        instance.update();
                        gs.info('Assessment instance state updated to in_progress');
                    } else {
                        gs.info('Assessment instance state is ' + instance.state + ', not updating');
                    }
                }
            }
			if (action === 'submit') {
               instanceId = question.instance.toString();
                gs.info('Updating assessment instance state to complete: ' + instanceId);

                instance = new GlideRecord('asmt_assessment_instance');
                // instance.setWorkflow(false); // Bypass workflows

                if (instance.get(instanceId)) {
                    // Only update if current state is 'ready' to avoid overwriting completed assessments
                    if (instance.state == 'ready' || instance.state == 'wip') {
                        instance.state = 'complete';
                        instance.update();
                        gs.info('Assessment instance state updated to complete');
                    } else {
                        gs.info('Assessment instance state is ' + instance.state + ', not updating');
                    }
                }

			}

            // Mark as processed
            // current.x_631631_sc_grc_0_processed = true;
            // current.update();

        } else {
            gs.error('Question not found: ' + questionId);
        }
    } catch (e) {
        gs.error('Error processing external attestation: ' + e.message);
    }
})(current, previous);
